<?php require_once __DIR__.'/../includes/bootstrap.php';require_role('Student');check_csrf();$qid=(int)($_GET['id']??$_POST['id']??0);$q=db()->prepare('SELECT * FROM quizzes WHERE id=? AND status="Published"');$q->execute([$qid]);$quiz=$q->fetch();if(!$quiz)exit('Quiz not found');$qs=db()->prepare('SELECT * FROM quiz_questions WHERE quiz_id=? ORDER BY id');$qs->execute([$qid]);$questions=$qs->fetchAll();$s=db()->prepare('SELECT id FROM students WHERE user_id=?');$s->execute([actor_id()]);$sid=(int)$s->fetchColumn();if($_SERVER['REQUEST_METHOD']==='POST'){$score=0;foreach($questions as $x){if(($_POST['a_'.$x['id']]??'')===$x['correct_answer'])$score+=(float)$x['marks'];}$s=db()->prepare('INSERT INTO quiz_attempts(quiz_id,student_id,started_at,submitted_at,score,status) VALUES(?,?,NOW(),NOW(),?,"Submitted")');$s->execute([$qid,$sid,$score]);$aid=(int)db()->lastInsertId();$i=db()->prepare('INSERT INTO quiz_answers(attempt_id,question_id,answer,marks) VALUES(?,?,?,?)');foreach($questions as $x){$a=$_POST['a_'.$x['id']]??'';$m=($a===$x['correct_answer'])?(float)$x['marks']:0;$i->execute([$aid,$x['id'],$a,$m]);}$_SESSION['flash']=['success','Quiz submitted'];redirect('quiz.php');}page_top('Quiz Attempt');?><form method="post" class="card p-4"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=e($qid)?>"><h4><?=e($quiz['title'])?></h4><?php foreach($questions as $i=>$x):$opts=json_decode($x['options_json'],true)?:[];?><div class="border rounded p-3 mb-3"><strong><?=($i+1)?>. <?=e($x['question'])?></strong><?php foreach($opts as $k=>$v):?><div class="form-check"><input class="form-check-input" type="radio" name="a_<?=e($x['id'])?>" value="<?=e($k)?>"><label class="form-check-label"><?=e($k)?> — <?=e($v)?></label></div><?php endforeach;?></div><?php endforeach;?><button class="btn btn-primary">Submit</button></form><?php page_bottom(); ?>